std/emit.lang:
// ============================================================
// std/emit.lang - Code Generation Helpers for Reader Macros
// ============================================================
//
// This module provides helpers for generating lang source code.
// Readers output lang source text, and these functions make that easy.
//
// Example:
//   var code *u8 = emit_binop(emit_number(1), "+", emit_number(2));
//   // code = "(1 + 2)"
//

// ============================================================
// String Builder
// ============================================================
//
// Simple growable string buffer for building output.

struct StringBuilder {
    buf *u8;
    len i64;
    cap i64;
}

func sb_new() *StringBuilder {
    var sb *StringBuilder = alloc(24);
    sb.cap = 256;
    sb.buf = alloc(sb.cap);
    sb.len = 0;
    return sb;
}

func sb_grow(sb *StringBuilder, need i64) void {
    if sb.len + need >= sb.cap {
        var new_cap i64 = sb.cap * 2;
        while new_cap < sb.len + need {
            new_cap = new_cap * 2;
        }
        var new_buf *u8 = alloc(new_cap);
        var i i64 = 0;
        while i < sb.len {
            *(new_buf + i) = *(sb.buf + i);
            i = i + 1;
        }
        sb.buf = new_buf;
        sb.cap = new_cap;
    }
}

func sb_char(sb *StringBuilder, c i64) void {
    sb_grow(sb, 1);
    *(sb.buf + sb.len) = c;
    sb.len = sb.len + 1;
}

func sb_str(sb *StringBuilder, s *u8) void {
    while *s != 0 {
        sb_char(sb, *s);
        s = s + 1;
    }
}

func sb_int(sb *StringBuilder, n i64) void {
    if n < 0 {
        sb_char(sb, 45);  // '-'
        n = 0 - n;
    }
    if n == 0 {
        sb_char(sb, 48);  // '0'
        return;
    }
    // Count digits
    var temp i64 = n;
    var digits i64 = 0;
    while temp > 0 {
        digits = digits + 1;
        temp = temp / 10;
    }
    // Write digits
    var i i64 = digits - 1;
    while i >= 0 {
        var divisor i64 = 1;
        var j i64 = 0;
        while j < i {
            divisor = divisor * 10;
            j = j + 1;
        }
        var digit i64 = (n / divisor) % 10;
        sb_char(sb, 48 + digit);
        i = i - 1;
    }
}

func sb_finish(sb *StringBuilder) *u8 {
    sb_char(sb, 0);
    return sb.buf;
}

// ============================================================
// Emit Helpers
// ============================================================

// emit_number(42) -> "42"
func emit_number(n i64) *u8 {
    var sb *StringBuilder = sb_new();
    sb_int(sb, n);
    return sb_finish(sb);
}

// emit_binop("1", "+", "2") -> "(1 + 2)"
func emit_binop(left *u8, op *u8, right *u8) *u8 {
    var sb *StringBuilder = sb_new();
    sb_char(sb, 40);  // '('
    sb_str(sb, left);
    sb_char(sb, 32);  // ' '
    sb_str(sb, op);
    sb_char(sb, 32);  // ' '
    sb_str(sb, right);
    sb_char(sb, 41);  // ')'
    return sb_finish(sb);
}

// emit_unary("-", "5") -> "(-5)"
func emit_unary(op *u8, operand *u8) *u8 {
    var sb *StringBuilder = sb_new();
    sb_char(sb, 40);  // '('
    sb_str(sb, op);
    sb_str(sb, operand);
    sb_char(sb, 41);  // ')'
    return sb_finish(sb);
}

// emit_call("foo", ["1", "2"]) -> "foo(1, 2)"
// args is a Vec of *u8 strings
func emit_call(func_name *u8, args *u8) *u8 {
    var sb *StringBuilder = sb_new();
    sb_str(sb, func_name);
    sb_char(sb, 40);  // '('
    var n i64 = vec_len(args);
    var i i64 = 0;
    while i < n {
        if i > 0 {
            sb_char(sb, 44);  // ','
            sb_char(sb, 32);  // ' '
        }
        var arg *u8 = vec_get(args, i);
        sb_str(sb, arg);
        i = i + 1;
    }
    sb_char(sb, 41);  // ')'
    return sb_finish(sb);
}

// emit_string("hello") -> "\"hello\""
// Handles escaping of special characters
func emit_string(s *u8) *u8 {
    var sb *StringBuilder = sb_new();
    sb_char(sb, 34);  // '"'
    while *s != 0 {
        var c i64 = *s;
        if c == 34 {         // '"'
            sb_char(sb, 92); // '\'
            sb_char(sb, 34);
        } else if c == 92 {  // '\'
            sb_char(sb, 92);
            sb_char(sb, 92);
        } else if c == 10 {  // newline
            sb_char(sb, 92);
            sb_char(sb, 110); // 'n'
        } else if c == 13 {  // carriage return
            sb_char(sb, 92);
            sb_char(sb, 114); // 'r'
        } else if c == 9 {   // tab
            sb_char(sb, 92);
            sb_char(sb, 116); // 't'
        } else {
            sb_char(sb, c);
        }
        s = s + 1;
    }
    sb_char(sb, 34);  // '"'
    return sb_finish(sb);
}

// emit_ident just returns the string as-is (identifiers don't need quoting)
func emit_ident(name *u8) *u8 {
    return str_dup(name);
}

// emit_paren wraps an expression in parentheses
func emit_paren(expr *u8) *u8 {
    var sb *StringBuilder = sb_new();
    sb_char(sb, 40);  // '('
    sb_str(sb, expr);
    sb_char(sb, 41);  // ')'
    return sb_finish(sb);
}

std/ast.lang:
// std/ast.lang - AST Builder API for Reader Authors
//
// Build S-expr AST without touching strings. Think in trees.
//
// Usage:
//   include "std/ast.lang"
//   return ast_binop("+", ast_number("1"), ast_number("2"));
//   // Returns: "(binop + (number 1) (number 2))"
//
// Every function returns *u8 (S-expr text). Compose by nesting.
//
// AST Versions:
//   v1 (legacy): string values include quotes in S-expr (e.g., "\"hello\"")
//   v2 (clean):  string values are raw content (e.g., "hello")
//
// Use ast_use_version(2) before building AST for v2 format.
// Use ast_version_decl() to get the version declaration for the program.

include "std/core.lang"
include "std/emit.lang"

// ============================================================
// AST Version Control
// ============================================================

var ast_output_version i64 = 2;  // v2: strings stored raw (no surrounding quotes)

func ast_use_version(v i64) void {
    ast_output_version = v;
}

func ast_current_version() i64 {
    return ast_output_version;
}

// Returns "(ast-version N)" declaration for program header
// Returns empty string for v1 (no declaration needed)
func ast_version_decl() *u8 {
    if ast_output_version == 1 {
        return "";
    }
    var sb *StringBuilder = sb_new();
    sb_str(sb, "(ast-version ");
    sb_int(sb, ast_output_version);
    sb_str(sb, ")");
    return sb_finish(sb);
}

// ============================================================
// Internal helpers
// ============================================================

func ast_sb() *StringBuilder {
    return sb_new();
}

func ast_finish(sb *StringBuilder) *u8 {
    return sb_finish(sb);
}

// Attach a zero-based, half-open byte range in the reader's input. The
// compiler binds it to the custom source file when it consumes reader output.
func ast_span(node *u8, start i64, end i64) *u8 {
    var sb *StringBuilder = ast_sb();
    sb_str(sb, "(span ");
    sb_int(sb, start);
    sb_str(sb, " ");
    sb_int(sb, end);
    sb_str(sb, " ");
    sb_str(sb, node);
    sb_str(sb, ")");
    return ast_finish(sb);
}

// Quote a string value for S-expr output (v1 format).
// Parser convention: string values include quotes (e.g., "hello" = 7 chars).
// So ast_string("hello") must produce S-expr that parses back to "hello" with quotes.
// Output: "\"hello\"" which sexpr_parse_string turns into "hello" (7 chars).
func ast_quote_string_v1(sb *StringBuilder, s *u8) void {
    sb_char(sb, '"');     // S-expr opening quote
    sb_char(sb, '\\');    // Escape for value quote
    sb_char(sb, '"');     // Value opening quote (part of the string value)
    while *s != 0 {
        var c u8 = *s;
        if c == '"' { sb_char(sb, '\\'); sb_char(sb, '"'); }
        else if c == '\\' { sb_char(sb, '\\'); sb_char(sb, '\\'); }
        else if c == '\n' { sb_char(sb, '\\'); sb_char(sb, 'n'); }
        else if c == '\t' { sb_char(sb, '\\'); sb_char(sb, 't'); }
        else if c == '\r' { sb_char(sb, '\\'); sb_char(sb, 'r'); }
        else { sb_char(sb, c); }
        s = s + 1;
    }
    sb_char(sb, '\\');    // Escape for value quote
    sb_char(sb, '"');     // Value closing quote (part of the string value)
    sb_char(sb, '"');     // S-expr closing quote
}

// Quote a string value for S-expr output (v2 format).
// Clean convention: string values are raw content (e.g., "hello" = 5 chars).
// Output: "hello" - just quoted for S-expr, sexpr_reader adds quotes.
func ast_quote_string_v2(sb *StringBuilder, s *u8) void {
    sb_char(sb, '"');
    while *s != 0 {
        var c u8 = *s;
        if c == '"' { sb_char(sb, '\\'); sb_char(sb, '"'); }
        else if c == '\\' { sb_char(sb, '\\'); sb_char(sb, '\\'); }
        else if c == '\n' { sb_char(sb, '\\'); sb_char(sb, 'n'); }
        else if c == '\t' { sb_char(sb, '\\'); sb_char(sb, 't'); }
        else if c == '\r' { sb_char(sb, '\\'); sb_char(sb, 'r'); }
        else { sb_char(sb, c); }
        s = s + 1;
    }
    sb_char(sb, '"');
}

// Version-aware string quoting - uses current ast_output_version
func ast_quote_string(sb *StringBuilder, s *u8) void {
    if ast_output_version >= 2 {
        ast_quote_string_v2(sb, s);
    } else {
        ast_quote_string_v1(sb, s);
    }
}

// ============================================================
// Vec helpers (for variadic arguments)
// ============================================================

func ast_vec() *u8 {
    return vec_new(8);
}

func ast_push(v *u8, item *u8) void {
    vec_push(v, item);
}

func ast_vec_len(v *u8) i64 {
    return vec_len(v);
}

func ast_vec_get(v *u8, i i64) *u8 {
    return vec_get(v, i);
}

// ============================================================
// Types
// ============================================================

// (type_base name) - e.g., i64, bool, void
func ast_type(name *u8) *u8 {
    var sb *StringBuilder = ast_sb();
    sb_str(sb, "(type_base ");
    sb_str(sb, name);
    sb_str(sb, ")");
    return ast_finish(sb);
}

// (type_ptr elem)
func ast_type_ptr(elem *u8) *u8 {
    var sb *StringBuilder = ast_sb();
    sb_str(sb, "(type_ptr ");
    sb_str(sb, elem);
    sb_str(sb, ")");
    return ast_finish(sb);
}

// (type_array size elem) - e.g. int[8] -> (type_array 8 (type_base i64))
func ast_type_array(size *u8, elem *u8) *u8 {
    var sb *StringBuilder = ast_sb();
    sb_str(sb, "(type_array ");
    sb_str(sb, size);
    sb_str(sb, " ");
    sb_str(sb, elem);
    sb_str(sb, ")");
    return ast_finish(sb);
}

// (type_func (param_types...) ret)
func ast_type_func(param_types *u8, ret *u8) *u8 {
    var sb *StringBuilder = ast_sb();
    sb_str(sb, "(type_func (");
    var i i64 = 0;
    var len i64 = ast_vec_len(param_types);
    while i < len {
